return {name="Seamwater Comb",inspect=function(ctx) local s=ctx.sanity local i=ctx.insight local c=ctx.charges local t=ctx.state if c==0 then return "The comb weighs almost nothing. A last bead clings where a tooth is gone." end if t==0 then if c==1 then return "One tooth is gone. The bead there is thin as a silk thread, and the ivory is dry." end if s<50 then return "The ivory is cold as a cup left out. One tooth is missing, and the gap looks wet." end return "A slim ivory comb. One tooth is gone. A still bead sits in the gap, and the ivory is dry." end if t==1 then return "The gap was wiped. The bead has returned, no larger, and your thumb is still dry." end if t<4 then return "The same bead, or a twin of it. It holds the light and gives none back." end if i>100 then return "The wet gap nearly makes a letter, then fails, and you cannot say which letter." end if s<40 then return "Cold climbs the teeth. The absent one keeps a bead that will not fall or wet you." end return "A pale line of water fills the missing tooth, then thins before it can mean anything." end,apply=function(ctx) local s=ctx.sanity local i=ctx.insight local c=ctx.charges local t=ctx.state if c==0 then return {text="You pass the comb and nothing changes. The small shine in the gap stays put.",state=t,sanity_delta=0} end local n=t+1 if n>255 then n=255 end local text="You draw the comb once. The bead rides the gap and leaves no damp behind." local d=-1 if s<40 then text="Cold runs the comb. The bead swells by a breath, then is the same size again." d=-2 elseif c==1 then text="The bead draws itself into a bright line and stops short of a shape." d=-1 elseif i>300 and t>=1 then text="You take it for a kept flaw in the ivory. The water stays, which spoils the thought." d=0 elseif s>=85 and t==0 then text="Only ivory, and one lost tooth. The bead may be a trick of the polish." d=0 elseif t==0 then text="You draw the comb once. The bead rides the gap and leaves no damp behind." d=-1 elseif t==1 then text="Again the bead. It should have broken on the tooth beside it. It only shifts." d=-1 elseif t==2 then text="A second pass finds the bead seated, as though the wipe had never happened." d=-1 elseif t<6 then if i>50 and s>=40 and s<80 and c>1 then text="For a breath the gap is only a gap, and the bead is only water." d=1 else text="The water is in the gap again, small and exact, with no source you can see." d=-1 end else text="The line almost becomes a word. You set the comb down before it can." if s>=70 then d=0 else d=-1 end end return {text=text,state=n,sanity_delta=d} end}